function binomCDF(n, p, k) {
  if (k < 0) return 0;
  if (k >= n) return 1;
  let c = 0;
  let term = Math.pow(1-p, n);
  c = term;
  for (let i = 1; i <= k; i++) {
    term = term * (n - i + 1) / i * p / (1-p);
    c += term;
  }
  return c;
}
function findMinNReject(p0, alpha) {
  for (let n = 1; n <= 10000; n++) {
    for (let c = 0; c <= n; c++) {
      const prob = 1 - binomCDF(n, p0, c-1);
      if (prob <= alpha) return {n, c, prob};
    }
  }
  return null;
}
function findMinNAccept(p0, beta) {
  for (let n = 1; n <= 10000; n++) {
    for (let c = 0; c <= n; c++) {
      const prob = binomCDF(n, p0, c);
      if (prob <= beta) return {n, c, prob};
    }
  }
  return null;
}
const p0 = 0.1;
const alpha1 = 0.05;
const beta2 = 0.1;
const r1 = findMinNReject(p0, alpha1);
const r2 = findMinNAccept(p0, beta2);
const out = {
  n1: r1.n,
